const std = @import("std");

pub fn main() !void {
    const text = "AAABBBCCCDDDDEE";
    var i: usize = 0;

    while (i < text.len) {
        const ch = text[i];
        var count: u32 = 1;
        while (i + count < text.len and text[i + count] == ch) {
            count += 1;
        }
        std.debug.print("{c}{}", .{ch, count});
        i += count;
    }
    std.debug.print("\n", .{});
}
